# AUTOGENERATED KERNEL (LLM)
# Source: LLM-generated candidate implementation
# Status: Experimental / uncurated
# Expectation: Correctness-first, performance not representative

import torch
import torch.nn as nn
import triton
import triton.language as tl


@triton.jit
def _mul_combine(a, b):
    return a * b


@triton.autotune(
    configs=[
        triton.Config({"BLOCK_SIZE": 512}, num_warps=4),
        triton.Config({"BLOCK_SIZE": 1024}, num_warps=4),
        triton.Config({"BLOCK_SIZE": 2048}, num_warps=8),
    ],
    key=["N"],
)
@triton.jit
def _cumprod_kernel(
    x_ptr,
    out_ptr,
    M,
    N,
    stride_m,
    stride_n,
    BLOCK_SIZE: tl.constexpr,
):
    row = tl.program_id(0)

    running_prod = 1.0

    for col_start in range(0, N, BLOCK_SIZE):
        cols = col_start + tl.arange(0, BLOCK_SIZE)
        mask = cols < N

        x = tl.load(
            x_ptr + row.to(tl.int64) * stride_m + cols * stride_n, mask=mask, other=1.0
        ).to(tl.float32)

        cum = tl.associative_scan(x, 0, _mul_combine)

        cum = cum * running_prod

        tl.store(
            out_ptr + row.to(tl.int64) * stride_m + cols * stride_n, cum, mask=mask
        )

        block_product = tl.reduce(x, 0, _mul_combine)
        running_prod = running_prod * block_product


def cumprod_triton(x, dim):
    assert dim == 1
    M, N = x.shape
    out = torch.empty_like(x)

    grid = (M,)
    _cumprod_kernel[grid](
        x,
        out,
        M,
        N,
        x.stride(0),
        x.stride(1),
    )
    return out


class Model(nn.Module):
    def __init__(self, dim):
        super(Model, self).__init__()
        self.dim = dim

    def forward(self, x):
        return cumprod_triton(x, self.dim)
